from lib import *
S = SS('t7')
steps = [
    step("空回滚:Try 请求超时或丢了,管理器发了 Cancel,Cancel 先到服务端,而 Try 从来没有执行过。朴素版(第 6 篇的写法)在有 CHECK(balance >= 0 and frozen >= 0) 的表上,Cancel 每次都报 3819,管理器只能一直重试,账户保持 (1000, 0, 0)。没有 CHECK 时 Cancel 执行成功,状态变成 (balance, frozen, spent) = (1080, -80, 0):凭空多出 80 块钱,frozen 变成负数。防护版的 Cancel 发现没有 Try 记录,返回 EMPTY,账户仍是 (1000, 0, 0),只在 tcc_log 里记一条 ('x1', 'CANCELLED')。", t=tl(S(1)), mark=lidx(S(1), '(1080, -80, 0)'), done=lidx(S(1), '防护版:Cancel 返回 EMPTY'), b=bars([['朴素版 Cancel 后 balance', 1080, '1080(多了 80)'], ['朴素版 Cancel 后 frozen', -80, '-80'], ['防护版 Cancel 后 balance', 1000, '1000']], 1100, mark=[0, 1], done=[2]), kv=KV([['朴素版', '多退 80,frozen 为负'], ['有 CHECK', 'Cancel 永远失败,只能重试'], ['防护版', '只记 CANCELLED,不改业务列']], ['防护版'])),
    step("悬挂:Cancel 先到(空回滚)、Try 后到。第一步的补救写法是让 Cancel 先检查 frozen 够不够(“宽容 Cancel”):Cancel 先到时什么都不改,状态保持 (1000, 0, 0);可随后迟到的 Try 到达并执行成功,状态变成 (920, 80, 0)——80 块钱被冻结,管理器已经走完流程,再也不会有人 Confirm 或 Cancel,这就是悬挂。防护版:Cancel 先到时在 tcc_log 里记下 CANCELLED,迟到的 Try 一上来 INSERT 就主键冲突,被拒绝,状态仍是 (1000, 0, 0)。防空回滚的那一行记录同时也是防悬挂的凭证。", t=tl(S(2)), mark=lidx(S(2), '(920, 80, 0)'), done=lidx(S(2), '防护版:Cancel 先到'), b=bars([['宽容 Cancel 版:最终 frozen', 80, '80(永久卡住)'], ['防护版:最终 frozen', 0, '0']], 80, mark=[0], done=[1]), kv=KV([['宽容 Cancel', '空回滚没事,悬挂出现'], ['防护版', 'Try 发现 CANCELLED 记录就拒绝'], ['凭证', '同一条 tcc_log 记录']], ['凭证'])),
    step("重复:确认包丢了,管理器按至少一次重发,同一个动作执行两次。朴素版 Try → Confirm 一次得 (920, 0, 80);同一个 Confirm 再来一次变成 (920, -80, 160):spent 记了 160、frozen 变成 -80。Try → Cancel 一次回到 (1000, 0, 0);同一个 Cancel 再来一次变成 (1080, -80, 0):balance 多了 80。防护版 Try → Confirm 后再重复 Confirm 两次,状态一直是 (920, 0, 80),tcc_log 里是 ('x3', 'CONFIRMED');Cancel 重复同理。重复的动作看到状态已经是目标状态,什么都不做,这就是幂等。", t=tl(S(3)), mark=lidx(S(3), '(920, -80, 160)', '(1080, -80, 0)'), done=lidx(S(3), '防护版:Try → Confirm', '防护版:Try → Cancel'), b=bars([['朴素版重复 Confirm 后 spent', 160, '160(应为 80)'], ['防护版重复 Confirm 后 spent', 80, '80']], 170, mark=[0], done=[1]), kv=KV([['朴素版', '每次重复都再改一遍'], ['防护版', '状态已是目标状态就直接返回'], ['前提', '管理器至少一次地重发']], ['前提'])),
    step("穷举一个 xid 所有可能的消息到达顺序:Try 可能丢、可能重复,Cancel / Confirm 可能重复,Cancel 可以抢在 Try 前面,Confirm 总在第一个 Try 之后,共 23 条序列(取消路径 16 条、确认路径 7 条)。正确终态:取消路径回到 (1000, 0, 0),确认路径是 (920, 0, 80)。朴素版 23 条里 14 条终态不对(frozen 变成负数 6 条、预留卡住 5 条、其它 3 条);宽容 Cancel 版 23 条里 15 条不对(卡住 11 条);防护版 23 条全部正确。例如取消路径 C → T,宽容版的终态是 (920, 80, 0);C → C 朴素版是 (1160, -160, 0)。(为了让错误显现,朴素版和宽容版跑在没有 CHECK 的表上。)", t=tl(S(4)), mark=lidx(S(4), '朴素版:23 条序列里 14 条', '宽容 Cancel 版:23 条序列里 15 条'), done=lidx(S(4), '防护版:23 条序列里 0 条'), b=bars([['朴素版 终态不对', 14, '14 / 23'], ['宽容 Cancel 版 终态不对', 15, '15 / 23'], ['防护版 终态不对', 0, '0 / 23']], 23, mark=[0, 1], done=[2]), kv=KV([['23 条序列', '取消路径 16 + 确认路径 7'], ['朴素 / 宽容 / 防护', '14 / 15 / 0 条终态不对'], ['结论', '三个问题要一起防']], ['结论'])),
    step("并发到达:Try 和 Cancel 同时到服务端(两个线程用屏障同时放行),重复 300 次。防护版终态不是初始状态的次数 0 / 300;宽容 Cancel 版 164 / 300(Cancel 先到时预留卡住);朴素版终态 0 / 300,因为 Try 和 Cancel 只是加减,先后顺序不同终态一样,但 Cancel 先到时中间状态 frozen 是负数,另一个线程不停读,读到了 665 次。并发安全靠 tcc_log 的主键:Try 的 INSERT 和 Cancel 的 INSERT IGNORE 在同一个 xid 上必有一个先成功,另一个看到它。", t=tl(S(5)), mark=lidx(S(5), '宽容 Cancel 版', '朴素版'), done=lidx(S(5), '防护版'), b=bars([['宽容 Cancel 版 终态不对', 164, '164 / 300'], ['朴素版 中间读到负数的次数', 665, '665'], ['防护版 终态不对', 0, '0 / 300']], 700, mark=[0, 1], done=[2]), kv=KV([['宽容 Cancel', '164 / 300 终态不对'], ['朴素版', '终态对,中间读到 frozen 为负'], ['防护版', '0 / 300']], ['防护版'])),
    step("防护的代价:每个动作多一次 tcc_log 的读写。Try 的中位数从 155 µs 到 344 µs(2.2 倍),Confirm 从 118 µs 到 307 µs(2.6 倍)。tcc_log 里 10 万行占 9.5 MiB,平均每行约 100 字节(含主键索引),每笔 TCC 事务每个参与的服务一行。tcc_log 不能立刻删:Cancel 记下的 CANCELLED 行被过早清理后,迟到的 Try 到达,又执行成功,状态变成 (920, 80, 0),再次悬挂。保留期必须比一条消息在网络里最长能晃多久还长。", t=tl(S(6)), mark=lidx(S(6), '过早清理'), done=lidx(S(6), 'Try             ', 'Confirm         '), b=bars([['Try 朴素版 µs', 155, '155'], ['Try 防护版 µs', 344, '344'], ['Confirm 朴素版 µs', 118, '118'], ['Confirm 防护版 µs', 307, '307']], 350, cur=[0, 2], mark=[1, 3]), kv=KV([['延迟', '2.2 倍(Try)、2.6 倍(Confirm)'], ['存储', '每行约 100 字节'], ['清理', '保留期要长于消息最大延迟']], ['清理'])),
]
A = mkartt('t7', 7, '分布式事务,TCC,空回滚,悬挂,幂等,tcc_log,MySQL,真实验证,动画演示',
    '实测 TCC 的三个坑:Cancel 先到而 Try 没执行(空回滚)会让朴素版多退 80;Cancel 先到、Try 后到(悬挂)让预留永久卡住;重复的 Confirm / Cancel 让 spent 记成 160。穷举 23 条消息顺序:朴素 14 条、宽容 15 条终态不对,带 tcc_log 防护的 0 条;防护让 Try 慢 2.2 倍,tcc_log 不能过早清理。',
    '第 6 篇的 TCC 在理想的网络里没问题。但真实的网络会让消息迟到、乱序、重复:Cancel 比 Try 先到、Try 迟到、Confirm 发两遍。这篇把这三类问题一个个复现,再用一张 tcc_log 把它们一起防住,并穷举所有消息顺序来验证。',
    [('14 / 23', '朴素版在 23 条消息到达顺序里终态不对的条数(带 tcc_log 防护的是 0 / 23)'), ('(920, 80, 0)', '悬挂:Cancel 先到、Try 迟到后,账户最终的 (balance, frozen, spent),80 块钱永久冻结'), ('2.2 倍', '防护让 Try 的延迟中位数变成的倍数(155 µs 到 344 µs)')],
    [('空回滚', '<p>Try 没执行,Cancel 先到。朴素版会把没冻结过的钱退回,凭空多出 80;有 CHECK 时则 Cancel 永远失败。防护版发现没有 Try 记录,只记一条 CANCELLED。</p>'),
     ('悬挂', '<p>Cancel 先到、Try 迟到。只修空回滚而不记录 Cancel 来过,迟到的 Try 会冻结资源,而管理器早已结束。防护版靠同一条 CANCELLED 记录,让迟到的 Try 被主键冲突拒绝。</p>'),
     ('重复', '<p>确认包丢了,管理器重发。朴素版每次都再改一遍:spent 变成 160、frozen 变成 -80。防护版看到状态已是目标状态就直接返回。</p>'),
     ('穷举验证', '<p>23 条消息顺序里,朴素版 14 条、宽容 Cancel 版 15 条终态不对,带 tcc_log 的版本全部正确。三个问题要一起防,只修一个不够。</p>'),
     ('并发到达', '<p>Try 和 Cancel 同时到达,防护版 0 / 300;并发安全来自 tcc_log 主键,同一个 xid 上只有一个能先成功。</p>'),
     ('代价与保留期', '<p>每个动作多一次 tcc_log 读写,延迟约 2 倍,每行约 100 字节。记录不能过早清理,否则迟到的消息又能造成悬挂。</p>')],
    steps,
    [ENV_T + '。本篇用一个 MySQL 26.7.0 实例上的账户服务;三种实现是我自己写的 Python(tools/articles/tcc.py:朴素版、宽容 Cancel 版、带 tcc_log 防护的版本);“消息迟到、乱序、重复”是在测试里按指定顺序直接调用服务来模拟的,不是真实网络里的丢包;朴素版和宽容版的穷举跑在去掉 CHECK 的表上以便错误显现',
     '没有验证:真实网络里消息迟到的最大时延(所以 tcc_log 的保留期没有给出具体数值);多个服务之间的联合行为(只测了账户这一个服务);Seata、Hmily 等框架怎么实现这三个防护;tcc_log 在分库分表或多活下的行为;“其它”3 条终态不对的序列没有逐条分析'],
    'TCC 的坑')
